def fetch(r):
 name,url,path,sub=r
 try:
  q=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'});res=urllib.request.urlopen(q,timeout=14);b=res.read(600000);enc=res.headers.get_content_charset() or ('gb18030' if b'charset=gb' in b[:6000].lower() else 'utf-8');text=b.decode(enc,errors='replace');m=re.search(r'<title[^>]*>(.*?)</title>',text,re.S|re.I);title=html.unescape(re.sub('<[^>]+>','',m.group(1))).strip() if m else ''
  return dict(name=name,url=url,path=path,subcategory=sub,status=res.status,finalUrl=res.url,title=title[:250],observed='2026-10-19',qualified=bool(title and not re.search(r'403|404|Access Denied|Just a moment|Attention Required|安全验证|访问验证',title,re.I)))
 except Exception as e:return dict(name=name,url=url,path=path,subcategory=sub,error=str(e)[:160],qualified=False)
